package com.chondrimaishrat.elearning.review;
import com.chondrimaishrat.elearning.course.*; import com.chondrimaishrat.elearning.enrollment.EnrollmentRepository; import com.chondrimaishrat.elearning.user.UserAccount; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ReviewService {private final ReviewRepository reviews;private final CourseRepository courses;private final EnrollmentRepository enrollments; public ReviewService(ReviewRepository r,CourseRepository c,EnrollmentRepository e){reviews=r;courses=c;enrollments=e;} @Transactional public void add(UserAccount s,Long courseId,int stars,String comment){if(stars<1||stars>5)throw new IllegalArgumentException("Rating must be between 1 and 5.");if(!enrollments.existsByStudentIdAndCourseId(s.getId(),courseId))throw new IllegalArgumentException("Only enrolled students can review this course.");if(reviews.existsByStudentIdAndCourseId(s.getId(),courseId))throw new IllegalArgumentException("You already reviewed this course.");reviews.save(new Review(s,courses.findById(courseId).orElseThrow(),stars,comment==null?"":comment.trim()));}}
